window.kbPageData["views/entry/k-484bd793f96d3d75"] = {"key":"entry/k-484bd793f96d3d75","state":{"route":"entry/k-484bd793f96d3d75"},"node":{"id":"k-484bd793f96d3d75","mode":"k","title":"充分条件假言命题的否后推否前","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 地市级 行测#110"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若前件成立必然后件成立，那么后件不成立时，前件也不成立。前件一旦成立，就必须满足后件所述条件。","review":{"definition":"若前件成立必然后件成立，那么后件不成立时，前件也不成立。前件一旦成立，就必须满足后件所述条件。","explanation":"题组要求研发部门一旦值班，其后一天就须由后勤部门值班。题设排除了整个假期的后勤值班，因此研发也无法值班。财务已被题设排除，第二天又按题组规则不能安排法务，而每天必须有一人值班，所以第二天只能由销售或人事部门的人值班，C项一定正确。","references":[],"evidence":"若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 行测#110":{"paper":"国考 2023 地市级 行测","n":110,"mod":"判断推理","src":["64bc3a15d27a04e94940.pdf",21],"asrc":["f3ab652d8e31c5bbdabc.pdf",36],"card":"f8e08e5dbf3f86f0f701e656","links":[{"id":"k-484bd793f96d3d75","role":"解题依据","why":"若前件成立必然后件成立，则否定后件可以推出前件不成立。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-484bd793f96d3d75":[["国考 2023 地市级 行测#110"]]}};
